/*
 * mmix_stub.c - placeholders for the functions that mmix_rt.c calls but
 * that are written in assembly (mmix_io.asm) or generated by the translator
 * (mmx_program).  build.sh compiles this file only so that the C11
 * compiler accepts mmix_rt.c as a module; the result is discarded.
 */
typedef unsigned long long octa;
long mmx_program(void) { return 0; }
long mmx_putb(long port, long b) { return port + b; }
long mmx_getb(long port) { return port; }
long mmx_open(octa *packed_name) { return packed_name != 0; }
long mmx_isfile(octa *packed_name) { return packed_name != 0; }
long mmx_delete(octa *packed_name) { return packed_name != 0; }
long mmx_close(long port) { return port; }
long mmx_seek(long port, long pos) { return port + pos; }
long mmx_tell(long port) { return port; }
octa *mmx_alloc(long words) { return (octa *)words; }
long mmx_exit(long code) { return code; }
long mmx_argc(void) { return 0; }
octa *mmx_arg(long i) { return (octa *)i; }
